head.script:
//
/* Smart Choice loader: يجلب أحدث smart-choice.js من GitHub (كاش 5 دقائق) بدل الاعتماد على كاش CDN الطويل. */
(function () {
  var raw = "https://raw.githubusercontent.com/tahattaha41/Smart-Choice/main/assets/js/smart-choice.js";
  var cdn = "https://cdn.jsdelivr.net/gh/tahattaha41/Smart-Choice@main/assets/js/smart-choice.js";
  function viaCdn() { var s = document.createElement("script"); s.src = cdn + "?v=" + Math.floor(Date.now() / 600000); document.head.appendChild(s); }
  try {
    fetch(raw + "?t=" + Math.floor(Date.now() / 300000), { credentials: "omit" })
      .then(function (r) { if (!r.ok) { throw new Error(r.status); } return r.text(); })
      .then(function (code) { var s = document.createElement("script"); s.textContent = code; document.head.appendChild(s); })
      .catch(viaCdn);
  } catch (e) { viaCdn(); }
})();
//

window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-BRZP957SQ4');

// /*SC-AD-GATE*/
  (function(){
    var CLIENT='ca-pub-1235197294708204',MIN=350,tries=0,done=false;
    function words(el){return (el.innerText||'').split(/\s+/).filter(function(w){return w.length>1;}).length;}
    function eligible(){
      var m=document.querySelector('meta[name="sc-pagetype"]'),pt=m?m.getAttribute('content'):'';
      var path=location.pathname;
      if(pt!=='item'&&pt!=='static_page')return false;
      if(path==='/'||/^\/search/.test(path)||/\/404/.test(path))return false;
      var main=document.querySelector('#main-content');if(!main)return false;
      if(main.querySelector('.sc-tabs,#sc-admin,.sc-admin,#sc-rates-board,.hero,.hcalc'))return false;
      if(pt==='static_page'&&!main.querySelector('.sc-tool,.sc-guide,.sc-prose'))return false;
      var c=main.cloneNode(true);c.querySelectorAll('nav,.sc-share-bar,.sc-related,form,button,script,style').forEach(function(n){n.remove();});
      return (c.textContent||'').split(/\s+/).filter(function(w){return w.length>1;}).length>=MIN;
    }
    function load(){if(done)return;done=true;var s=document.createElement('script');s.async=true;s.crossOrigin='anonymous';s.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+CLIENT;document.head.appendChild(s);}
    function check(){if(done)return;tries++;try{if(eligible()){load();return;}}catch(e){}if(tries<8)setTimeout(check,900);}
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(check,600);});else setTimeout(check,600);
  })();
  //

head.b:skin:
/* ===== Smart Choice — نظام التصميم v2 (مدمج في القالب: لا وميض ولا اعتماد على ملفات خارجية) ===== */
:root{--bg:#f4f6fa;--surface:#fff;--soft:#eef2f8;--ink:#0f172a;--hd:#0b1324;--muted:#556178;--line:#e2e8f0;
--brand:#0f766e;--brand-d:#0b5a54;--brand-t:#e0f2f0;--accent:#f59e0b;--night:#0b1324;--night2:#111c33;
--c-pay:#2563eb;--c-loan:#e11d48;--c-save:#0f766e;--c-shop:#d97706;--c-biz:#7c3aed;--c-gold:#b7791f;
--rust:#b4451f;--ochre:#b7791f;--r:14px;--w:1180px;--sh:0 1px 2px rgba(15,23,42,.06),0 10px 30px rgba(15,23,42,.07);--sh2:0 2px 4px rgba(15,23,42,.08),0 18px 40px rgba(15,23,42,.12);
--font:"IBM Plex Sans Arabic","Segoe UI",Tahoma,system-ui,-apple-system,Arial,sans-serif}
html[data-sc-theme="dark"]{--bg:#080d19;--surface:#111a2d;--soft:#172238;--ink:#e6ecf8;--hd:#f4f7fd;--muted:#9aa8c4;--line:#223049;--brand:#2dd4bf;--brand-d:#5eead4;--brand-t:#10302f;--night:#050914;--night2:#0c1424;
--c-pay:#60a5fa;--c-loan:#fb7185;--c-save:#2dd4bf;--c-shop:#fbbf24;--c-biz:#a78bfa;--c-gold:#e7b04a;--sh:0 1px 2px rgba(0,0,0,.4),0 10px 30px rgba(0,0,0,.35);--sh2:0 18px 44px rgba(0,0,0,.55)}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--font);font-size:17px;line-height:1.85;-webkit-font-smoothing:antialiased}
img,svg{max-width:100%}
a{color:var(--brand-d);text-decoration:none}a:hover{text-decoration:underline}
h1,h2,h3,h4{color:var(--hd);line-height:1.4;margin:0 0 .5em;font-weight:700}
p{margin:0 0 1em}
.wrap{width:min(var(--w),calc(100% - 32px));margin-inline:auto}
.ic{width:1.25em;height:1.25em;flex:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;vertical-align:-.2em}
.sc-skip{position:absolute;inset-inline-start:12px;top:-70px;background:var(--surface);color:var(--ink);padding:10px 14px;border-radius:8px;z-index:1000}.sc-skip:focus{top:8px}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.btn,.sc-btn,.sc-ghost{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 24px;border-radius:12px;font:inherit;font-weight:700;font-size:16px;line-height:1.4;border:1.5px solid transparent;cursor:pointer;text-decoration:none!important;transition:transform .15s,background .15s,border-color .15s,color .15s,box-shadow .15s}
.btn,.sc-btn{background:var(--brand);color:#fff;box-shadow:0 6px 16px rgba(15,118,110,.28)}
.btn:hover,.sc-btn:hover{background:var(--brand-d);color:#fff;transform:translateY(-1px)}
.btn.alt,.sc-btn.alt,.sc-ghost{background:transparent;color:var(--ink);border-color:color-mix(in srgb,var(--ink) 25%,transparent);box-shadow:none}
.btn.alt:hover,.sc-btn.alt:hover,.sc-ghost:hover{border-color:var(--brand);color:var(--brand-d);background:var(--brand-t);transform:none}
.btn.sm{padding:8px 16px;font-size:14.5px}
.chip{display:inline-block;padding:3px 11px;border-radius:99px;background:var(--brand-t);color:var(--brand-d);font-size:13px;font-weight:600;line-height:1.7}

/* ----- الترويسة ----- */
.nav-t{position:absolute;opacity:0;pointer-events:none}
.top{position:sticky;top:0;z-index:50;background:color-mix(in srgb,var(--surface) 92%,transparent);-webkit-backdrop-filter:saturate(1.4) blur(12px);backdrop-filter:saturate(1.4) blur(12px);border-bottom:1px solid var(--line)}
.bar{display:flex;align-items:center;gap:16px;min-height:68px}
.logo{display:flex;align-items:center;gap:10px;color:var(--hd);font-weight:800;font-size:22px;letter-spacing:-.2px;text-decoration:none!important}
.logo svg{width:36px;height:36px;border-radius:10px}
.logo b{color:var(--brand)}
.nav{display:flex;align-items:center;gap:2px;margin-inline-start:12px}
.nav>a,.mega>a{display:flex;align-items:center;gap:5px;padding:9px 13px;border-radius:10px;color:var(--ink);font-weight:600;font-size:15.5px;text-decoration:none!important;white-space:nowrap}
.nav>a:hover,.mega>a:hover,.mega:focus-within>a{background:var(--soft);color:var(--brand-d)}
.nav a[aria-current=page]{color:var(--brand-d);background:var(--brand-t)}
.mega{position:relative}
.mega>a .ic{width:14px;height:14px;transition:transform .2s}
.mega:hover>a .ic{transform:rotate(180deg)}
.mega-p{display:none;position:absolute;inset-inline-start:-140px;top:100%;width:min(860px,92vw);padding:22px;margin-top:6px;background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:var(--sh2);grid-template-columns:repeat(3,1fr);gap:18px 24px}
.mega:hover .mega-p,.mega:focus-within .mega-p{display:grid}
.mega-p::before{content:"";position:absolute;inset-inline:0;top:-10px;height:10px}
.mega-p h4{display:flex;align-items:center;gap:8px;font-size:15px;margin:0 0 6px;color:var(--c,var(--brand))}
.mega-p h4 .ic{width:20px;height:20px}
.mega-p a{display:block;padding:4px 0;color:var(--muted);font-size:14.5px;line-height:1.6;text-decoration:none!important}
.mega-p a:hover{color:var(--brand-d)}
.mega-p .all{grid-column:1/-1;border-top:1px solid var(--line);padding-top:12px;margin-top:2px;font-weight:700;color:var(--brand-d);font-size:15px}
.srch{display:flex;margin-inline-start:auto;position:relative}
.srch input{width:190px;padding:9px 40px 9px 14px;border:1.5px solid var(--line);border-radius:12px;background:var(--soft);color:var(--ink);font:inherit;font-size:15px;transition:width .2s,border-color .2s}
.srch input:focus{width:260px;border-color:var(--brand);outline:0;background:var(--surface)}
.srch button{position:absolute;inset-inline-end:4px;top:50%;transform:translateY(-50%);border:0;background:none;color:var(--muted);padding:6px;cursor:pointer;display:grid;place-items:center}
.theme{border:1.5px solid var(--line);background:var(--surface);color:var(--ink);width:42px;height:42px;border-radius:12px;display:grid;place-items:center;cursor:pointer;flex:none}
.theme:hover{border-color:var(--brand);color:var(--brand-d)}
.theme .i-sun{display:none}
html[data-sc-theme="dark"] .theme .i-sun{display:block}html[data-sc-theme="dark"] .theme .i-moon{display:none}
.burger{display:none;width:42px;height:42px;border:1.5px solid var(--line);border-radius:12px;place-items:center;cursor:pointer;color:var(--ink);background:var(--surface)}
@media(max-width:980px){
 .burger{display:grid;margin-inline-start:auto}
 .srch{display:none}
 .nav{display:none;position:absolute;inset-inline:0;top:100%;flex-direction:column;align-items:stretch;gap:0;margin:0;padding:10px 16px 18px;background:var(--surface);border-bottom:1px solid var(--line);box-shadow:var(--sh2);max-height:calc(100vh - 68px);overflow:auto}
 .nav-t:checked~.top .nav{display:flex}
 .nav>a,.mega>a{padding:13px 8px;border-radius:0;border-bottom:1px solid var(--line)}
 .mega>a .ic{display:none}
 .mega-p{display:block;position:static;width:auto;padding:4px 4px 8px;margin:0;border:0;border-radius:0;box-shadow:none;background:none}
 .mega-p>div{margin-bottom:8px}
 .mega-p a{display:inline-block;margin-inline-end:12px}
 .mega-p .all{display:block;border:0;padding:6px 0}
 .nav .srch-m{display:flex;margin:12px 0 0}
}
.srch-m{display:none}
.srch-m input{flex:1;width:auto;padding:12px 14px;border:1.5px solid var(--line);border-radius:12px;background:var(--soft);color:var(--ink);font:inherit}
.srch-m button{margin-inline-start:8px;padding:0 16px;border:0;border-radius:12px;background:var(--brand);color:#fff;font:inherit;font-weight:700}

/* ----- التذييل ----- */
.foot{background:var(--night);color:#b9c4dc;margin-top:72px;padding:56px 0 0}
.foot a{color:#d7dff0;text-decoration:none}.foot a:hover{color:#fff;text-decoration:underline}
.foot-g{display:grid;grid-template-columns:1.5fr repeat(3,1fr);gap:36px}
.foot h4{color:#fff;font-size:16px;margin-bottom:14px}
.foot ul{list-style:none;margin:0;padding:0}.foot li{margin:0 0 9px;font-size:15px;line-height:1.6}
.foot .logo{color:#fff;margin-bottom:12px}.foot .logo b{color:#5eead4}
.foot p{font-size:15px;line-height:1.9;max-width:340px}
.foot-b{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:40px;padding:20px 0 24px;border-top:1px solid rgba(255,255,255,.1);font-size:14px;color:#8d9ab8}
.foot-note{margin-top:28px;padding:16px 18px;border-radius:12px;background:rgba(255,255,255,.05);font-size:14px;line-height:1.8;color:#a8b4ce}
@media(max-width:820px){.foot-g{grid-template-columns:1fr 1fr}.foot-g>div:first-child{grid-column:1/-1}}
.sc-totop{position:fixed;inset-inline-start:16px;bottom:18px;width:44px;height:44px;border:0;border-radius:50%;background:var(--brand);color:#fff;font-size:20px;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .2s;box-shadow:var(--sh2);z-index:40}
.sc-totop.show{opacity:1;pointer-events:auto}


/* ----- الصفحة الرئيسية ----- */
.site-main{padding:0 0 8px;min-height:60vh}
.hero{position:relative;overflow:hidden;background:linear-gradient(180deg,var(--surface),var(--bg));border-bottom:1px solid var(--line)}
.hero::before{content:"";position:absolute;inset:0;background-image:radial-gradient(circle at 1px 1px,color-mix(in srgb,var(--ink) 11%,transparent) 1px,transparent 0);background-size:26px 26px;-webkit-mask-image:linear-gradient(180deg,#000,transparent 85%);mask-image:linear-gradient(180deg,#000,transparent 85%);pointer-events:none}
.hero-in{position:relative;display:grid;grid-template-columns:1.12fr .88fr;gap:52px;align-items:center;padding:62px 0 58px}
.kicker{display:inline-flex;align-items:center;gap:8px;padding:6px 14px 6px 12px;border:1px solid var(--line);border-radius:99px;background:var(--surface);font-size:14px;font-weight:600;color:var(--muted);margin-bottom:18px}
.kicker i{width:8px;height:8px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px rgba(34,197,94,.18)}
.hero h1{font-size:clamp(32px,4.3vw,52px);line-height:1.25;letter-spacing:-.6px;margin-bottom:18px}
.hero h1 span{color:var(--brand);position:relative;white-space:nowrap}
.hero h1 span::after{content:"";position:absolute;inset-inline:0;bottom:2px;height:10px;background:color-mix(in srgb,var(--accent) 45%,transparent);z-index:-1;border-radius:4px}
.lead{font-size:19px;line-height:2;color:var(--muted);max-width:590px;margin-bottom:26px}
.cta{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:26px}
.quick{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:14.5px;color:var(--muted)}
.quick a{padding:5px 13px;border:1px solid var(--line);border-radius:99px;background:var(--surface);color:var(--ink);font-weight:600;font-size:14px;text-decoration:none!important}
.quick a:hover{border-color:var(--brand);color:var(--brand-d)}
.hcalc{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:24px 26px;box-shadow:var(--sh2)}
.hcalc-h{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px}
.hcalc-h b{font-size:17px;color:var(--hd)}
.hcalc-h a{font-size:13.5px;font-weight:700}
.hcalc label{display:block;font-size:14px;font-weight:600;color:var(--muted);margin:0 0 4px}
.hcalc .row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px}
.hcalc input{width:100%;padding:11px 13px;border:1.5px solid var(--line);border-radius:11px;background:var(--soft);color:var(--ink);font:inherit;font-size:17px}
.hcalc input:focus{outline:0;border-color:var(--brand);background:var(--surface)}
.hcalc-out{display:grid;grid-template-columns:1.3fr 1fr;gap:12px}
.hcalc-out div{border-radius:14px;padding:12px 15px;background:var(--soft)}
.hcalc-out div:first-child{background:var(--night);color:#cfd8ec}
.hcalc-out small{display:block;font-size:13px;opacity:.85}
.hcalc-out strong{display:block;font-size:28px;line-height:1.35;color:var(--hd);font-variant-numeric:tabular-nums}
.hcalc-out div:first-child strong{color:#fff;font-size:32px}
.hbar{display:flex;height:10px;border-radius:99px;overflow:hidden;background:var(--line);margin:16px 0 8px}
.hbar i{display:block;height:100%;transition:width .4s}
.hbar .a{background:var(--brand)}.hbar .b{background:var(--accent)}.hbar .c{background:var(--c-biz)}
.hleg{display:flex;gap:16px;flex-wrap:wrap;font-size:13px;color:var(--muted)}
.hleg span::before{content:"";display:inline-block;width:9px;height:9px;border-radius:3px;margin-inline-end:6px;background:var(--brand)}
.hleg .b::before{background:var(--accent)}.hleg .c::before{background:var(--c-biz)}
.hcalc-n{margin:12px 0 0;font-size:12.5px;color:var(--muted);line-height:1.7}
@media(max-width:900px){.hero-in{grid-template-columns:1fr;gap:34px;padding:38px 0 40px}}

.stats{display:grid;grid-template-columns:repeat(4,1fr);background:var(--surface);border:1px solid var(--line);border-radius:18px;margin-top:-28px;position:relative;box-shadow:var(--sh)}
.stats>div{padding:20px 22px;text-align:center;border-inline-start:1px solid var(--line)}
.stats>div:first-child{border-inline-start:0}
.stats b{display:block;font-size:30px;line-height:1.3;color:var(--brand-d);font-variant-numeric:tabular-nums}
.stats span{font-size:14.5px;color:var(--muted)}
@media(max-width:700px){.stats{grid-template-columns:1fr 1fr}.stats>div:nth-child(3){border-inline-start:0}.stats>div:nth-child(n+3){border-top:1px solid var(--line)}.stats b{font-size:26px}}

.sec{padding:58px 0 0}
.sec-h{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:22px}
.sec-h h2{font-size:clamp(24px,3.2vw,32px);margin:0}
.sec-h p{margin:6px 0 0;color:var(--muted);font-size:16px;line-height:1.8}
.sec-h>a{font-weight:700;font-size:15px;white-space:nowrap;display:inline-flex;align-items:center;gap:6px}

#sc-rates-strip{min-height:0}
.sc-rates-wrap{margin-top:0}
.sc-rs{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.sc-rcard{display:flex;flex-direction:column;gap:2px;padding:14px 16px;background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--sh)}
.sc-rcard b{font-size:14px;font-weight:600;color:var(--muted)}
.sc-rcard strong{font-size:22px;line-height:1.4;font-variant-numeric:tabular-nums;color:var(--hd)}
.sc-rcard strong small{font-size:13px;font-weight:500;color:var(--muted)}
.sc-rcard>small{font-size:13px;color:var(--muted)}
.sc-rcard .up{color:#16a34a}.sc-rcard .down{color:#dc2626}
.sc-ticker-link{display:inline-block;margin-top:10px;font-weight:700;font-size:14.5px}
.sc-rgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}
.sc-rates-meta,.sc-rates-src{font-size:13px;color:var(--muted)}
@media(max-width:820px){.sc-rs{grid-template-columns:1fr 1fr}}

.cats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.cat{--c:var(--brand);position:relative;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:24px 24px 20px;box-shadow:var(--sh);transition:transform .2s,box-shadow .2s,border-color .2s}
.cat:hover{transform:translateY(-3px);box-shadow:var(--sh2);border-color:color-mix(in srgb,var(--c) 45%,var(--line))}
.cat-pay{--c:var(--c-pay)}.cat-loan{--c:var(--c-loan)}.cat-save{--c:var(--c-save)}.cat-shop{--c:var(--c-shop)}.cat-biz{--c:var(--c-biz)}.cat-gold{--c:var(--c-gold)}
.cat-i{display:grid;place-items:center;width:52px;height:52px;border-radius:15px;background:color-mix(in srgb,var(--c) 13%,transparent);color:var(--c);margin-bottom:14px}
.cat-i .ic{width:26px;height:26px}
.cat h3{font-size:20px;margin-bottom:4px}
.cat>p{color:var(--muted);font-size:15px;line-height:1.8;margin-bottom:12px}
.cat ul{list-style:none;margin:0 0 14px;padding:0;flex:1}
.cat li a{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 0;border-top:1px solid var(--line);color:var(--ink);font-size:15.5px;font-weight:500;text-decoration:none!important}
.cat li a .ic{width:15px;height:15px;color:var(--muted);transition:transform .15s}
.cat li a:hover{color:var(--c)}.cat li a:hover .ic{color:var(--c);transform:translateX(-3px)}
.cat-more{font-weight:700;font-size:14.5px;color:var(--c);display:inline-flex;align-items:center;gap:6px}
@media(max-width:980px){.cats{grid-template-columns:1fr 1fr}}
@media(max-width:640px){.cats{grid-template-columns:1fr}}

.asks{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;counter-reset:ask}
.ask{counter-increment:ask;position:relative;display:block;padding:22px 22px 20px;background:var(--surface);border:1px solid var(--line);border-radius:18px;color:var(--ink);text-decoration:none!important;transition:border-color .2s,transform .2s,box-shadow .2s}
.ask::before{content:counter(ask,arabic-indic);position:absolute;inset-inline-end:18px;top:12px;font-size:44px;font-weight:800;color:color-mix(in srgb,var(--brand) 14%,transparent);line-height:1}
.ask:hover{border-color:var(--brand);transform:translateY(-3px);box-shadow:var(--sh)}
.ask b{display:block;font-size:18px;line-height:1.6;color:var(--hd);margin-bottom:6px;padding-inline-end:34px}
.ask span{display:inline-flex;align-items:center;gap:6px;font-size:14px;font-weight:700;color:var(--brand-d)}
@media(max-width:900px){.asks{grid-template-columns:1fr 1fr}}@media(max-width:600px){.asks{grid-template-columns:1fr}}

.posts{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.pcard{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:var(--sh);transition:transform .2s,box-shadow .2s}
.pcard:hover{transform:translateY(-3px);box-shadow:var(--sh2)}
.pcard-top{height:8px;background:var(--c,var(--brand))}
.pcard-b{display:flex;flex-direction:column;gap:8px;padding:20px 22px 18px;flex:1}
.pcard h3{font-size:19px;line-height:1.6;margin:0}
.pcard h3 a{color:var(--hd);text-decoration:none}.pcard h3 a:hover{color:var(--brand-d)}
.pcard p{margin:0;color:var(--muted);font-size:15px;line-height:1.85;flex:1}
.pcard-m{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:13.5px;color:var(--muted);padding-top:8px;border-top:1px solid var(--line)}
@media(max-width:980px){.posts{grid-template-columns:1fr 1fr}}@media(max-width:640px){.posts{grid-template-columns:1fr}}

.trust{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.trust>div{padding:26px 24px;border-radius:18px;background:var(--surface);border:1px solid var(--line)}
.trust .cat-i{background:var(--brand-t);color:var(--brand-d)}
.trust h3{font-size:19px}.trust p{margin:0;color:var(--muted);font-size:15.5px;line-height:1.9}
@media(max-width:820px){.trust{grid-template-columns:1fr}}
.band{display:flex;align-items:center;justify-content:space-between;gap:28px;padding:38px 42px;border-radius:24px;background:radial-gradient(600px 240px at 100% 0,color-mix(in srgb,var(--brand) 45%,transparent),transparent 70%),var(--night);color:#cdd7ec}
.band h2{color:#fff;margin:0 0 6px;font-size:28px}.band p{margin:0;max-width:640px;font-size:16.5px;line-height:1.9}
.band .btn{background:#fff;color:#0b1324;box-shadow:none;flex:none}.band .btn:hover{background:#e6fffb}
@media(max-width:760px){.band{flex-direction:column;align-items:flex-start;padding:28px 24px}}

/* ----- مقال / صفحة / تصنيف ----- */
.crumbs,.sc-crumbs{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:14px;color:var(--muted);margin:0 0 18px}
.crumbs a,.sc-crumbs a{color:var(--muted)}.crumbs a:hover,.sc-crumbs a:hover{color:var(--brand-d)}
.page-pad{padding-top:30px}
.post{max-width:780px;margin-inline:auto}
.post-h{margin-bottom:26px}
.post-h h1{font-size:clamp(28px,4.2vw,42px);line-height:1.45;margin:10px 0 14px}
.post-m{display:flex;flex-wrap:wrap;gap:6px 18px;align-items:center;color:var(--muted);font-size:14.5px;padding:12px 0;border-block:1px solid var(--line)}
.post-m span{display:inline-flex;align-items:center;gap:6px}
.prose{font-size:18px;line-height:2.05;color:var(--ink)}
.prose h2{font-size:28px;margin:46px 0 14px;padding-top:6px;scroll-margin-top:90px}
.prose h3{font-size:22px;margin:32px 0 10px}
.prose p{margin:0 0 1.2em}
.prose ul,.prose ol{padding-inline-start:1.4em;margin:0 0 1.3em}.prose li{margin:0 0 .5em}
.prose a{text-decoration:underline;text-underline-offset:3px;text-decoration-color:color-mix(in srgb,var(--brand) 45%,transparent)}
.prose strong{color:var(--hd)}
.prose table{width:100%;border-collapse:separate;border-spacing:0;margin:1.4em 0;font-size:16px;border:1px solid var(--line);border-radius:12px;overflow:hidden}
@media(max-width:640px){.prose table{display:block;overflow-x:auto}}
.post-m i{font-style:normal}
.prose th,.prose td{padding:11px 14px;text-align:start;border-bottom:1px solid var(--line)}
.prose th{background:var(--soft);color:var(--hd);font-weight:700}
.prose tr:last-child td{border-bottom:0}
.prose blockquote{margin:1.4em 0;padding:14px 20px;border-inline-start:4px solid var(--brand);background:var(--brand-t);border-radius:0 12px 12px 0}
.prose img{height:auto;border-radius:12px}
.prose .sc-bars{margin:1.4em 0;padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.toc{margin:0 0 30px;padding:18px 22px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.toc b{display:block;margin-bottom:8px;color:var(--hd)}
.toc ol{margin:0;padding-inline-start:1.3em;font-size:15.5px;line-height:2}
.toc a{color:var(--ink);text-decoration:none}.toc a:hover{color:var(--brand-d);text-decoration:underline}
.author{display:flex;gap:16px;align-items:center;margin:40px 0 0;padding:20px 22px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}
.author-i{width:56px;height:56px;border-radius:50%;background:var(--brand-t);color:var(--brand-d);display:grid;place-items:center;font-weight:800;font-size:22px;flex:none}
.author p{margin:0;color:var(--muted);font-size:15px;line-height:1.8}.author b{color:var(--hd);display:block;font-size:16.5px}
.tools-box{margin:36px 0 0;padding:22px 24px;border-radius:16px;background:var(--brand-t);border:1px solid color-mix(in srgb,var(--brand) 25%,transparent)}
.tools-box h2{font-size:21px;margin:0 0 6px}
.lhead{padding:44px 0 26px}
.lhead h1{font-size:clamp(28px,4.4vw,44px);margin:10px 0 10px}
.lhead p{color:var(--muted);max-width:720px;font-size:17.5px;line-height:1.95;margin:0}
.lhead .cat-i{margin-bottom:0}
.pager{display:flex;justify-content:space-between;gap:12px;margin:34px 0 0}
.pager a{padding:10px 20px;border:1.5px solid var(--line);border-radius:12px;background:var(--surface);font-weight:700;color:var(--ink);text-decoration:none!important}
.pager a:hover{border-color:var(--brand);color:var(--brand-d)}
.empty{text-align:center;padding:70px 0 40px}
.empty h1{font-size:clamp(34px,6vw,64px);margin-bottom:8px}
.empty p{color:var(--muted);max-width:520px;margin:0 auto 22px}
.docpage{max-width:1000px;margin-inline:auto;padding-top:22px}
.sc-readtime{display:inline-flex;margin:0 0 6px;color:var(--muted);font-size:14.5px}
.sc-share{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:26px 0}
.sc-share b{margin-inline-end:4px;font-size:15px}
.sc-share a,.sc-share button{padding:7px 14px;border:1.5px solid var(--line);border-radius:10px;background:var(--surface);color:var(--ink);font:inherit;font-size:14px;font-weight:600;cursor:pointer;text-decoration:none!important}
.sc-share a:hover,.sc-share button:hover{border-color:var(--brand);color:var(--brand-d)}
.sc-related{margin-top:34px}.sc-related h2{font-size:22px}
.sc-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}
.sc-card{padding:16px 18px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}
.sc-card h3{font-size:17px;margin:0}.sc-card a{color:var(--hd)}
.sc-post-meta,.sc-byline{color:var(--muted);font-size:14px}


/* ----- الحاسبات وصفحات الأدوات (تُبنى بعناصر JS لكن التصميم كله هنا) ----- */
.sc-page{max-width:var(--w);margin:0 auto;padding:26px 0 8px;color:var(--ink);line-height:1.85}
.sc-page.sc-toolpage,.sc-page.sc-doc{max-width:900px}
.sc-tools-hero{padding:6px 0 18px}
.sc-tools-hero h1{font-size:clamp(28px,4.4vw,44px);margin:0 0 10px}
.sc-tools-hero p{margin:0;color:var(--muted);font-size:17.5px;line-height:1.95;max-width:760px}
.sc-muted{color:var(--muted);font-size:15px}
.sc-tool-card{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:clamp(18px,3vw,30px);margin:0 0 18px;box-shadow:var(--sh)}
.sc-tool-card h2{font-size:25px;margin:0 0 6px}
.sc-tool-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:16px 0}
.sc-field label{display:block;font-weight:600;font-size:15px;margin-bottom:5px;color:var(--ink)}
.sc-page input,.sc-page select,.sc-page textarea{width:100%;padding:11px 14px;border:1.5px solid var(--line);border-radius:12px;background:var(--soft);color:var(--ink);font:inherit;font-size:17px;transition:border-color .15s,background .15s,box-shadow .15s}
.sc-page input:focus,.sc-page select:focus,.sc-page textarea:focus{outline:0;border-color:var(--brand);background:var(--surface);box-shadow:0 0 0 4px var(--brand-t)}
.sc-page input[type=checkbox],.sc-page input[type=radio]{width:auto}
.sc-tool-result{margin-top:14px;padding:16px 18px;border-radius:14px;background:var(--soft);font-size:17px;line-height:1.9}
.sc-tool-result strong{color:var(--hd)}
.sc-tool-result.sc-kpis{background:none;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.kpi{padding:14px 16px;border:1px solid var(--line);border-radius:14px;background:var(--surface);animation:scPop .35s ease both}
.kpi span{display:block;font-size:14px;color:var(--muted);line-height:1.6}
.kpi b,.kpi strong{display:block;font-size:22px;line-height:1.5;color:var(--hd);font-variant-numeric:tabular-nums}
.kpi.main{grid-column:1/-1;padding:20px 24px;border:0;background:radial-gradient(500px 200px at 100% 0,color-mix(in srgb,var(--brand) 55%,transparent),transparent 70%),var(--night)}
.kpi.main span{color:#b9c8e6}.kpi.main b{color:#fff;font-size:clamp(30px,5.5vw,44px)}
@keyframes scPop{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media(max-width:640px){.sc-tool-result.sc-kpis{grid-template-columns:1fr 1fr}}
.sc-tool[hidden]{display:none!important}
.sc-crumbs{margin-bottom:16px}
.sc-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
.sc-share-bar{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.sc-share-bar button,.sc-share-bar a,.sc-tool-result>button{padding:6px 14px;border:1.5px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted);font:inherit;font-size:13.5px;font-weight:600;cursor:pointer;text-decoration:none}
.sc-share-bar button:hover,.sc-share-bar a:hover{border-color:var(--brand);color:var(--brand-d)}
.sc-chipbtn{margin:2px;padding:3px 11px;border:1px solid var(--line);border-radius:99px;background:var(--surface);color:var(--ink);font:inherit;font-size:13.5px;cursor:pointer}
.sc-chipbtn:hover{border-color:var(--brand);color:var(--brand-d)}
.sc-demo-note,.sc-disc{font-size:13.5px;color:var(--muted)}
.sc-guide,.sc-prose{max-width:820px;font-size:17.5px;line-height:2}
.sc-tool-card.sc-guide{background:none;border:0;box-shadow:none;padding:6px 0 0}
.sc-guide h2,.sc-prose h2{font-size:25px;margin:34px 0 10px}
.sc-guide table,.sc-prose table{width:100%;border-collapse:collapse;margin:1em 0;font-size:16px;display:block;overflow-x:auto}
.sc-guide th,.sc-guide td,.sc-prose th,.sc-prose td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:start}
.sc-guide th,.sc-prose th{background:var(--soft)}
.sc-page details{border:1px solid var(--line);border-radius:12px;padding:2px 16px;margin:8px 0;background:var(--surface)}
.sc-page summary{cursor:pointer;padding:12px 0;font-weight:700;color:var(--hd)}

/* فهرس الحاسبات */
.sc-page:has(>.sc-tabs){display:flex;flex-direction:column}
.sc-page:has(>.sc-tabs)>*{order:5}
.sc-page:has(>.sc-tabs)>.sc-tools-hero{order:0}
.sc-page:has(>.sc-tabs)>#sc-assistant{order:1}
.sc-page:has(>.sc-tabs)>.sc-filter{order:2}
.sc-page:has(>.sc-tabs)>.sc-tabs{order:3}
#sc-assistant{border:2px solid var(--brand);border-radius:20px;background:var(--surface);box-shadow:0 0 0 6px var(--brand-t),var(--sh)}
.sc-tabs [data-tab=assistant]{display:none}
.sc-filter{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px 16px;margin:26px 0 8px;padding-top:22px;border-top:1px solid var(--line)}
.sc-filter input{flex:0 1 300px;min-width:0}
.sc-chips{display:flex;flex-wrap:wrap;gap:6px}
.sc-chips button{display:inline-flex;align-items:center;gap:6px;padding:7px 16px;border:1.5px solid var(--line);border-radius:99px;background:var(--surface);color:var(--ink);font:inherit;font-size:14.5px;font-weight:600;cursor:pointer}
.sc-chips button[aria-pressed=true]{background:var(--brand);border-color:var(--brand);color:#fff}
.sc-tabs{display:grid;grid-template-columns:repeat(2,1fr);gap:12px 16px;margin:10px 0 30px}
.sc-tabs button{display:grid;grid-template-columns:48px 1fr;grid-template-areas:"i n" "i d";gap:0 14px;align-items:center;text-align:start;padding:14px 16px;border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--ink);font:inherit;cursor:pointer;box-shadow:var(--sh);transition:transform .15s,border-color .15s,box-shadow .15s}
.sc-tabs button:hover,.sc-tabs button[aria-selected=true]{transform:translateY(-2px);border-color:var(--brand);box-shadow:var(--sh2)}
.sc-ti{grid-area:i;display:grid;place-items:center;width:48px;height:48px;border-radius:14px;background:var(--brand-t);color:var(--brand-d)}
.sc-tabs button>span:not(.sc-ti){grid-area:n;font-weight:700;font-size:17px;line-height:1.5;color:var(--hd)}
.sc-td{grid-area:d;color:var(--muted);font-size:14px;font-weight:400;line-height:1.6}
@media(max-width:760px){.sc-tabs{grid-template-columns:1fr}}

/* رسوم الأدوات */
.sc-viz{margin:14px 0 0}.sc-viz:empty{display:none}
.sc-viz-row{display:flex;align-items:center;gap:24px;flex-wrap:wrap;background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:16px 18px;margin-bottom:12px}
.sc-viz-row.col{flex-direction:column;align-items:stretch}
.sc-viz-h{margin:12px 0 8px;font-weight:700;color:var(--hd);font-size:15.5px}
.sc-donut{width:150px;height:150px;flex:none}
.sc-donut .dt{font-size:6.6px;font-weight:700;fill:var(--hd)}.sc-donut .ds{font-size:3.2px;fill:var(--muted)}
.sc-legend{list-style:none;margin:0;padding:0;flex:1;min-width:200px;display:grid;gap:8px}
.sc-legend li{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 14px;border-radius:12px;background:var(--soft);border-inline-start:6px solid var(--c)}
.sc-legend span{color:var(--muted);font-size:14.5px}.sc-legend b{color:var(--hd);font-size:17px}
.sc-bars{display:grid;gap:9px}
.sc-bar{display:grid;grid-template-columns:110px 1fr auto;align-items:center;gap:10px;font-size:14.5px}
.sc-bar span{color:var(--muted)}.sc-bar i{display:block;height:14px;border-radius:99px;min-width:6px}
.sc-bar b{color:var(--hd);min-width:70px;text-align:end}
.sc-line{width:100%;height:auto;max-height:170px;display:block}
.sc-prog{height:14px;border-radius:99px;background:var(--line);overflow:hidden;margin:6px 0 4px}.sc-prog i{display:block;height:100%;border-radius:99px;background:var(--brand);transition:width .5s}
.sc-sched{margin-top:12px}.sc-sched summary{color:var(--brand-d)}
.sc-tw{overflow-x:auto}.sc-tw table{width:100%;border-collapse:collapse;font-size:14.5px;min-width:380px}
.sc-tw th,.sc-tw td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:start}.sc-tw th{background:var(--soft);color:var(--hd)}
.sc-save-btn{margin-top:10px;padding:8px 16px;font-size:14.5px}
.sc-saved{margin-top:14px;border:1.5px dashed var(--line);border-radius:14px;padding:10px 16px;background:var(--surface)}
.sc-saved ul{list-style:none;margin:0;padding:0}
.sc-saved li{display:flex;align-items:center;gap:8px;padding:8px 0;border-top:1px solid var(--line);font-size:14.5px}.sc-saved li:first-child{border-top:0}
.sc-saved li span{flex:1}.sc-saved li .sc-ghost{padding:4px 12px;font-size:13px}
.sc-conv{display:grid;grid-template-columns:1fr 1.3fr auto 1.3fr;gap:12px;align-items:end;background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:var(--sh)}
.sc-conv label{display:grid;gap:5px;font-weight:600;font-size:14px;color:var(--muted)}
.sc-conv-out{margin:12px 0 0;padding:16px 20px;border-radius:16px;background:var(--night);color:#fff;font-size:clamp(17px,2.6vw,22px);font-weight:700;line-height:1.7}
@media(max-width:700px){.sc-conv{grid-template-columns:1fr 1fr}.sc-conv>label:first-child{grid-column:1/-1}.sc-bar{grid-template-columns:84px 1fr auto}.sc-donut{width:130px;height:130px}}
.sc-offers-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}
.sc-offer{display:flex;gap:10px;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.sc-ad-tag{font-size:12px;color:var(--muted)}
@media print{.top,.foot,.sc-tabs,.sc-totop,.sc-share-bar{display:none}}

/* ---------- لوحة الإدارة ---------- */
.adm-app{display:grid;grid-template-columns:210px 1fr;gap:20px;align-items:start;max-width:var(--w);margin:0 auto}
.adm-tabs{position:sticky;top:70px;display:flex;flex-direction:column;gap:4px;padding:10px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r)}
.adm-tabs button{display:flex;align-items:center;gap:8px;padding:9px 12px;border:0;border-radius:8px;background:none;color:var(--ink);font:inherit;font-size:15px;font-weight:600;text-align:start;cursor:pointer}
.adm-tabs button:hover{background:var(--soft)}
.adm-tabs button[aria-selected=true]{background:var(--brand);color:var(--on-brand)}
.adm-tabs .adm-out{margin-top:8px;border-top:1px solid var(--line);border-radius:0 0 8px 8px;color:var(--muted)}
.adm-body{min-width:0;display:flex;flex-direction:column;gap:16px}
.adm-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}
.adm-stat{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}
.adm-lbl{display:block;font-size:13.5px;color:var(--muted)}
.adm-stat b{display:block;font-size:26px;line-height:1.3}
.adm-stat small{display:block;color:var(--muted);font-size:12.5px}
.adm-ico{color:var(--brand);float:inline-end}
.adm-stat.good b{color:var(--good)}
.adm-card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:16px 18px}
.adm-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin:0 0 10px}
.adm-h h2{margin:0;font-size:18px}
.adm-sub,html body .adm-muted{color:var(--muted);font-size:14px}
.adm-tbl{overflow-x:auto}
.adm-table{width:100%;border-collapse:collapse;font-size:14.5px}
.adm-table th{background:var(--soft);text-align:start;font-weight:700}
.adm-table th,html body .adm-table td{padding:8px 10px;border-bottom:1px solid var(--line)}
.adm-badge{display:inline-block;padding:1px 9px;border-radius:6px;background:var(--brand-t);color:var(--brand-d);font-size:12.5px;font-weight:700}
.adm-badge.bad{background:color-mix(in srgb,var(--bad) 18%,transparent);color:var(--bad)}
.adm-ok{color:var(--good)}html body .adm-bad{color:var(--bad)}
.adm-bars{display:flex;flex-direction:column;gap:6px}
.adm-bar{display:grid;grid-template-columns:90px 1fr 50px;gap:8px;align-items:center;font-size:13.5px}
.adm-list{margin:0;padding-inline-start:20px}
.adm-form{display:grid;gap:10px}
.adm-form input,html body .adm-form textarea,html body .adm-input{padding:9px 12px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;width:100%}
.adm-btn{padding:9px 18px;border:0;border-radius:8px;background:var(--brand);color:var(--on-brand);font:inherit;font-weight:700;cursor:pointer}
.adm-links{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:8px}
.adm-link{display:block;padding:10px 12px;border:1px solid var(--line);border-radius:8px;color:var(--ink)}
.adm-link:hover{border-color:var(--brand)}
html body input[type=checkbox],html body input[type=radio]{width:auto;accent-color:var(--brand)}
.adm-checks{list-style:none;padding:0;margin:0}
.adm-checks li{margin:6px 0}html body .adm-checks label{display:flex;gap:10px;align-items:flex-start;cursor:pointer}html body .adm-checks input{margin-top:6px;flex:none}
@media(max-width:820px){
  html body .adm-app{grid-template-columns:1fr}
  html body .adm-tabs{position:static;flex-direction:row;overflow-x:auto;padding:6px}
  html body .adm-tabs button{white-space:nowrap}
  html body .adm-tabs .adm-out{margin:0;border:0}
  html body .adm-table thead{display:none}
  html body .adm-table tr{display:block;border:1px solid var(--line);border-radius:8px;margin-bottom:8px;padding:4px 8px}
  html body .adm-table td{display:block;border:0;padding:3px 2px}
}


.hero h1 span{isolation:isolate}[hidden]{display:none!important}

body.script:
//
  (function(){
    var d=document,h=d.documentElement,K='sc-theme-v3';
    var tb=d.querySelector('.theme');if(tb)tb.addEventListener('click',function(){var n=h.getAttribute('data-sc-theme')==='dark'?'light':'dark';h.setAttribute('data-sc-theme',n);try{localStorage.setItem(K,n);}catch(e){}});
    var up=d.querySelector('.sc-totop');if(up){up.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});window.addEventListener('scroll',function(){up.classList.toggle('show',window.scrollY>700);},{passive:true});}
    var nt=d.getElementById('nav-t');d.querySelectorAll('.nav a').forEach(function(a){a.addEventListener('click',function(){if(nt)nt.checked=false;});});
    // مثال الراتب في الرئيسية
    var g=d.getElementById('hc-g');if(g){
      var B=[[40000,0],[55000,.10],[70000,.15],[200000,.20],[400000,.225],[1200000,.25],[1e15,.275]],i=d.getElementById('hc-i');
      function f(n){return Math.round(n).toLocaleString('ar-EG');}
      function up2(){var G=+g.value||0,I=+i.value||0,t=Math.max(0,(G-I)*12-20000),tx=0,p=0;for(var k=0;k<B.length;k++){if(t>p)tx+=(Math.min(t,B[k][0])-p)*B[k][1];p=B[k][0];}
        var m=tx/12,n=G-I-m;d.getElementById('hc-n').textContent=f(n)+' جنيه';d.getElementById('hc-t').textContent=f(m);
        var s=G>0?100/G:0;d.getElementById('hc-ba').style.width=(n*s)+'%';d.getElementById('hc-bb').style.width=(m*s)+'%';d.getElementById('hc-bc').style.width=(I*s)+'%';}
      g.addEventListener('input',up2);i.addEventListener('input',up2);up2();}
    // مقال: وقت القراءة وفهرس المحتوى
    var pb=d.querySelector('.post .prose');if(pb){
      var w=(pb.innerText||'').trim().split(/\s+/).length,m=Math.max(1,Math.round(w/180)),r=d.getElementById('rt');if(r)r.textContent='وقت القراءة '+m+(m===1?' دقيقة':' دقائق')+' · '+w+' كلمة';
      var hs=pb.querySelectorAll('h2');if(hs.length>=3){var o=d.createElement('nav');o.className='toc';o.setAttribute('aria-label','محتويات المقال');var l='<b>في هذا المقال</b><ol>';hs.forEach(function(e,k){e.id=e.id||'s'+(k+1);l+='<li><a href="#'+e.id+'">'+e.textContent+'</a></li>';});o.innerHTML=l+'</ol>';pb.insertBefore(o,pb.firstChild);}
    }
  })();
